//Inactive native D0 packets; WH19 appends decimal and two later footers.
static std::pair<size_t,size_t> stoppedBasesRange(const std::string& extra){auto at=extra.find("\nEFFECTBASES1 ");check(at!=std::string::npos,"current schema contains inactive D0 footer");++at;auto end=extra.find("\nINPUTREGION1 ",at);check(end!=std::string::npos,"WH19 InputRegion follows the complete inactive packet section");return {at,end+1};}
static std::string stoppedBasesFooter(const mahoyo::save::Document& document){check(currentHostSchema(document),"stopped packet helper uses actual WH19");std::string extra(document.hostExtra.begin(),document.hostExtra.end());auto range=stoppedBasesRange(extra);return extra.substr(range.first,range.second-range.first);}
static mahoyo::save::Document withStoppedBases(mahoyo::save::Document document,const std::string& footer){check(currentHostSchema(document),"stopped packet edits preserve actual WH19");std::string extra(document.hostExtra.begin(),document.hostExtra.end());auto range=stoppedBasesRange(extra);extra.replace(range.first,range.second-range.first,footer);document.hostExtra.assign(extra.begin(),extra.end());return document;}
static std::string stoppedBaseRow(const std::vector<std::string>& values){check(values.size()==35,"current stopped packet has exactly35 fields");std::ostringstream out;hostRow(out,values,35);return out.str();}
