    f.command("save","2");const auto good=mahoyo::save::read(f.root/"savedata/slot2.whs");const auto footer=stoppedBasesFooter(good);std::istringstream in(footer);std::string row;std::getline(in,row);check(row=="EFFECTBASES1 1","one stopped effect has its own counted footer");std::getline(in,row);const auto fields=hostFields(row);check(fields.size()==35&&fields[0]=="26"&&fields[1]=="1"&&fields[2]=="0"&&std::stod(fields[5])==100&&fields[34]=="0","inactive D0 uses canonical Effect35 packet with zero elapsed and explicit decimal");
