    for(auto edit:std::vector<std::pair<int,std::string>>{{0,"64"},{0,"25"},{1,"0"},{1,"8373"},{2,"1"},{2,"-1"},{3,"nan"},{4,"inf"},{7,"1.01"},{8,"-inf"},{9,"0"},{9,"101"},{10,"101"},{11,"1"},{13,"4096"},{16,"-1"},{19,"26"},{20,"83"},{21,"4294967295"},{22,"-1"},{23,"32768"},{26,"-1"},{27,"nan"},{28,"inf"},{29,"nan"},{30,"inf"},{31,"nan"},{32,"inf"},{33,"nan"},{34,"2147483648"},{34,"-2147483649"},{34,"nan"}}){auto malformed=fields;malformed[size_t(edit.first)]=edit.second;bad.push_back("EFFECTBASES1 1\n"+stoppedBaseRow(malformed));}
