    auto trailing=good;const std::string junk="trailing\n";trailing.hostExtra.insert(trailing.hostExtra.end(),junk.begin(),junk.end());mahoyo::save::writeAtomic(f.root/"savedata/slot2.whs",trailing);state=f.command("load","2");check(state.find("\"notice\":\"Loaded\"")==std::string::npos&&number(state,"instructions")==instructions&&visibleLayers(state)==original&&waiting(state,"input"),"trailing junk after both complete WH19 footers rejects atomically");
