    check(state.find("\"notice\":\"Loaded\"")!=std::string::npos&&visibleLayers(state)==original&&number(state,"nextTickMs")==0,"supported inactive root18 packet loads without sampling or replacing live graphics");
    state=f.command("advance");check(number(layerObject(state,27),"blend")==18&&number(layerObject(state,26),"blend")==0,"clone uses supported root18 D0 independently of the frozen root0 layer");
    mahoyo::save::writeAtomic(f.root/"savedata/slot2.whs",good);state=f.command("load","2");check(visibleLayers(state)==original,"restore original packet for remaining malformed cases");
